{
  "claims": [
    {
      "claim": "The bill takes effect July 1, 2025.",
      "summary_quote": "Beginning July 1, 2025",
      "verdict": "supported",
      "source_quote": "This act takes effect July 1, 2025, the public welfare requiring it.",
      "error_type": "none",
      "rationale": "The summary gives the specified effective date."
    },
    {
      "claim": "The Board of Regents, a state university board, or the University of Tennessee Board of Trustees would be required to provide a report upon a qualifying request.",
      "summary_quote": "the bill would require the Board of Regents, a state university board, or the University of Tennessee Board of Trustees to provide a report",
      "verdict": "supported",
      "source_quote": "the board of regents, a state university board, or the board of trustees of the\n University of Tennessee shall provide a report to the requesting committee",
      "error_type": "none",
      "rationale": "The summary accurately identifies the boards and the mandatory reporting duty, subject to the request condition stated later in the summary."
    },
    {
      "claim": "The report must summarize grievance activities of the previous year.",
      "summary_quote": "summarizing the previous year’s grievance activities",
      "verdict": "supported",
      "source_quote": "summarizing\n grievance activities of the previous year.",
      "error_type": "none",
      "rationale": "The report's subject and reporting period match the bill."
    },
    {
      "claim": "A request by the Senate Education Committee or the House committee with jurisdiction over education triggers the reporting requirement.",
      "summary_quote": "when requested by the Senate Education Committee or the House committee with jurisdiction over education",
      "verdict": "supported",
      "source_quote": "Upon the request of the education committee of the senate or the committee\n of the house of representatives having jurisdiction over subject matters pertaining to\n education",
      "error_type": "none",
      "rationale": "The summary preserves both eligible requesting committees and the request-based condition."
    }
  ]
}
